from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class MoLite(SchemaObject):
    mo_uuid = SchemaField(name="mo_uuid", not_null=True)
    parent_mo_uuid = SchemaField(name="parent_mo_uuid")
    nidd_id = SchemaField(name="nidd_id", not_null=True)
    name = SchemaField(name="name", not_null=True)
    has_definition_errors = SchemaField(name="has_definition_errors", not_null=True)
    has_relation_errors = SchemaField(name="has_relation_errors", not_null=True)
    has_children = SchemaField(name="has_children", not_null=True)
    state = SchemaField(name="state", not_null=True)

    def __init__(self, mo_uuid, parent_mo_uuid, nidd_id, name, has_definition_errors, has_relation_errors, has_children,
                 state):
        self.mo_uuid = mo_uuid
        self.parent_mo_uuid = parent_mo_uuid
        self.nidd_id = nidd_id
        self.name = name
        self.has_definition_errors = has_definition_errors
        self.has_relation_errors = has_relation_errors
        self.has_children = has_children
        self.state = state

        super(MoLite, self).__init__()


class PlanTreeDiffASMV1(SchemaObject):
    revision = SchemaField(name="revision", not_null=True)
    created = SchemaField(name="created", not_null=True, klass=MoLite, many=True)
    updated = SchemaField(name="updated", not_null=True, klass=MoLite, many=True)
    removed = SchemaField(name="removed", not_null=True)

    def __init__(self, revision, created, updated, removed):
        self.revision = revision
        self.created = created
        self.updated = updated
        self.removed = removed
        super(PlanTreeDiffASMV1, self).__init__()
